def count_digits(n: int) -> int:
    n = abs(n)
    if n == 0:
        return 1
    count = 0
    while n > 0:
        n //= 10      # drop last digit
        count += 1
    return count

def gcd(a: int, b: int) -> int:
    while b:          # Euclid: gcd(a, b) = gcd(b, a % b)
        a, b = b, a % b
    return a

