function minEatingSpeed(piles, h) {
    let l = 1, r = Math.max(...piles);
    let ans = r;
    while (l <= r) {
        const k = Math.floor((l + r) / 2);
        const hours = piles.reduce((acc, p) => acc + Math.ceil(p / k), 0);
        if (hours <= h) {
            ans = k; r = k - 1;
        } else l = k + 1;
    }
    return ans;
}

