function backspaceCompare(s, t) {
    function getValidIdx(str, idx) {
        let skip = 0;
        while (idx >= 0) {
            if (str[idx] === '#') { skip++; idx--; }
            else if (skip > 0) { skip--; idx--; }
            else break;
        }
        return idx;
    }
    let i = s.length - 1, j = t.length - 1;
    while (i >= 0 || j >= 0) {
        i = getValidIdx(s, i);
        j = getValidIdx(t, j);
        if (i >= 0 && j >= 0 && s[i] !== t[j]) return false;
        if ((i >= 0) !== (j >= 0)) return false;
        i--; j--;
    }
    return true;
}

