    let curr = 0;
    for (let i = 0; i < k; i++) curr += nums[i];
    let maxS = curr;
    for (let i = k; i < nums.length; i++) {
        curr += nums[i] - nums[i - k];
        maxS = Math.max(maxS, curr);
    }
    return maxS / k;
}

