function circularArrayLoop(nums) {
    const n = nums.length;
    function getNext(i, isForward) {
        const direction = nums[i] >= 0;
        if (isForward !== direction) return -1;
        let nextIdx = (i + nums[i]) % n;
        if (nextIdx < 0) nextIdx += n;
        if (nextIdx === i) return -1;
        return nextIdx;
    }
    for (let i = 0; i < n; i++) {
        const isForward = nums[i] >= 0;
        let slow = i, fast = i;
        while (true) {
            slow = getNext(slow, isForward);
            fast = getNext(fast, isForward);
            if (fast !== -1) fast = getNext(fast, isForward);
            if (slow === -1 || fast === -1) break;
            if (slow === fast) return true;
        }
    }
    return false;
}

