    const set = new Set(nums);
    let longest = 0;
    for (let num of set) {
        if (!set.has(num - 1)) {
            let curr = num;
            let streak = 1;
            while (set.has(curr + 1)) {
                curr++; streak++;
            }
            longest = Math.max(longest, streak);
        }
    }
    return longest;
}

