function maxProduct(nums) {
    let res = nums[0], maxP = nums[0], minP = nums[0];
    for (let i = 1; i < nums.length; i++) {
        const x = nums[i];
        if (x < 0) { const temp = maxP; maxP = minP; minP = temp; }
        maxP = Math.max(x, maxP * x);
        minP = Math.min(x, minP * x);
        res = Math.max(res, maxP);
    }
