function bfs(graph, start) {
  const dist = new Map([[start, 0]]);
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {   // index instead of shift(): O(1)
    const node = queue[head];
    for (const nxt of graph[node] ?? []) {
      if (!dist.has(nxt)) {
        dist.set(nxt, dist.get(node) + 1);
        queue.push(nxt);
      }
    }
  }
  return dist;
}

function topoSort(n, edges) {
  const graph = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [a, b] of edges) { graph[a].push(b); indeg[b]++; }
  const queue = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);
  const order = [];
  for (let head = 0; head < queue.length; head++) {
    const u = queue[head];
    order.push(u);
    for (const v of graph[u]) if (--indeg[v] === 0) queue.push(v);
  }
  return order.length === n ? order : []; // [] means a cycle
}

