function climbStairs(n) {
    if (n <= 2) return n;
    let a = 1, b = 2;
    for (let i = 3; i <= n; i++) {
        const temp = a + b;
        a = b; b = temp;
    }
    return b;
}

function rob(nums) {
    let rob1 = 0, rob2 = 0;
    for (let num of nums) {
        let temp = Math.max(rob1 + num, rob2);
        rob1 = rob2;
        rob2 = temp;
    }
    return rob2;
}

