from functools import cache

# 1) Top-down: write the recursion, then memoise it
def rob(nums):
    @cache
    def best(i):                       # best loot from houses i..end
        if i >= len(nums):
            return 0
        return max(best(i + 1),            # skip
                   nums[i] + best(i + 2))  # rob
    return best(0)

# 2) Bottom-up with O(1) space
def rob_iter(nums):
    prev2 = prev1 = 0
    for x in nums:
        prev2, prev1 = prev1, max(prev1, prev2 + x)
    return prev1

# 3) Coin Change: dp[a] = fewest coins to make amount a
def coin_change(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != INF else -1

# 4) 2D: Longest Common Subsequence
def lcs(a, b):
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[-1][-1]

